BEGIN;
ALTER TABLE agroway_identity.membership ADD COLUMN IF NOT EXISTS granted_permissions text[] NOT NULL DEFAULT ARRAY[]::text[];
CREATE TABLE IF NOT EXISTS agroway_identity.invitation(tenant_id uuid NOT NULL,invitation_id uuid NOT NULL,email text NOT NULL,invited_by_actor_id text NOT NULL,roles text[] NOT NULL,granted_permissions text[] NOT NULL DEFAULT ARRAY[]::text[],state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','ACCEPTED','REVOKED','EXPIRED')),created_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,accepted_actor_id text,PRIMARY KEY(tenant_id,invitation_id),CONSTRAINT invitation_creator_membership_fk FOREIGN KEY(tenant_id,invited_by_actor_id) REFERENCES agroway_identity.membership(tenant_id,actor_id),CONSTRAINT invitation_roles_allowed CHECK(roles <@ ARRAY['ADMIN','AGRONOMIST','OPERATOR','VIEWER','INVESTOR']::text[]),CONSTRAINT invitation_roles_nonempty CHECK(cardinality(roles)>0),CONSTRAINT invitation_expiry_after_creation CHECK(expires_at>created_at));
CREATE TABLE IF NOT EXISTS agroway_identity.subscription_entitlement(tenant_id uuid PRIMARY KEY,plan_tier text NOT NULL CHECK(plan_tier IN ('CAMPO','PRO','NETWORK','ENTERPRISE')),add_ons text[] NOT NULL DEFAULT ARRAY[]::text[],status text NOT NULL CHECK(status IN ('ACTIVE','PAST_DUE','SUSPENDED','CANCELLED')),seat_limit integer NOT NULL CHECK(seat_limit>0),effective_from timestamptz NOT NULL,effective_until timestamptz,CONSTRAINT subscription_addons_allowed CHECK(add_ons <@ ARRAY['PASSPORT','SENSORS','SANA_INTELLIGENCE','SANA_IMPACT']::text[]),CONSTRAINT subscription_window_valid CHECK(effective_until IS NULL OR effective_until>effective_from));
CREATE TABLE IF NOT EXISTS agroway_identity.data_export_request(tenant_id uuid NOT NULL,export_request_id uuid NOT NULL,requested_by_actor_id text NOT NULL,format text NOT NULL CHECK(format IN ('JSON','CSV')),scope text NOT NULL CHECK(scope IN ('LOCAL_FIELD_DATA','FULL_TENANT_DATA')),state text NOT NULL DEFAULT 'REQUESTED' CHECK(state IN ('REQUESTED','PROCESSING','READY','FAILED','EXPIRED')),requested_at timestamptz NOT NULL,completed_at timestamptz,object_ref text,digest_sha256 text,PRIMARY KEY(tenant_id,export_request_id),CONSTRAINT export_request_actor_membership_fk FOREIGN KEY(tenant_id,requested_by_actor_id) REFERENCES agroway_identity.membership(tenant_id,actor_id),CONSTRAINT export_request_digest_sha256 CHECK(digest_sha256 IS NULL OR digest_sha256 ~ '^[a-f0-9]{64}$'),CONSTRAINT export_ready_requires_artifact CHECK(state <> 'READY' OR (completed_at IS NOT NULL AND object_ref IS NOT NULL AND digest_sha256 IS NOT NULL)));
CREATE INDEX IF NOT EXISTS invitation_tenant_state_idx ON agroway_identity.invitation(tenant_id,state,expires_at);CREATE INDEX IF NOT EXISTS data_export_request_tenant_state_idx ON agroway_identity.data_export_request(tenant_id,state,requested_at DESC);
ALTER TABLE agroway_identity.membership ENABLE ROW LEVEL SECURITY;ALTER TABLE agroway_identity.membership FORCE ROW LEVEL SECURITY;ALTER TABLE agroway_identity.invitation ENABLE ROW LEVEL SECURITY;ALTER TABLE agroway_identity.invitation FORCE ROW LEVEL SECURITY;ALTER TABLE agroway_identity.subscription_entitlement ENABLE ROW LEVEL SECURITY;ALTER TABLE agroway_identity.subscription_entitlement FORCE ROW LEVEL SECURITY;ALTER TABLE agroway_identity.data_export_request ENABLE ROW LEVEL SECURITY;ALTER TABLE agroway_identity.data_export_request FORCE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['membership','invitation','subscription_entitlement','data_export_request'] LOOP IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='agroway_identity' AND tablename=t AND policyname=t||'_tenant_rls') THEN EXECUTE format('CREATE POLICY %I ON agroway_identity.%I USING (tenant_id = nullif(current_setting(''app.tenant_id'', true), '''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'', true), '''')::uuid)',t||'_tenant_rls',t); END IF; END LOOP; END $$;
REVOKE ALL ON agroway_identity.invitation FROM PUBLIC;REVOKE ALL ON agroway_identity.subscription_entitlement FROM PUBLIC;REVOKE ALL ON agroway_identity.data_export_request FROM PUBLIC;
COMMENT ON TABLE agroway_identity.invitation IS 'Tenant-bound invited-user lifecycle. Role/permission ceiling remains authoritative in identity-access service.';COMMENT ON TABLE agroway_identity.subscription_entitlement IS 'Tenant plan/add-on state used by fail-closed entitlement resolution.';COMMENT ON TABLE agroway_identity.data_export_request IS 'Portable data export request lifecycle. READY requires artifact reference and SHA-256 digest.';
COMMIT;
